import{_ as i,a0 as p,w as l,s as r,ao as c,I as o,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Docker 的用户名字空間功能 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Docker 的用户名字空間功能 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Docker 的用户名字空間功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Docker 的用户名字空間功能 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20171102 Using User Namespaces on Docker","title":"使用 Docker 的用户名字空間功能","tag":"201808","desc":""},"relativePath":"201808/20171102 Using User Namespaces on Docker.md","filePath":"[post].md"}'),d={name:"201808/20171102 Using User Namespaces on Docker.md"};function h(u,s,k,g,b,m){const n=p("Link");return l(),r("div",null,[s[15]||(s[15]=c(`<h1 id="使用-docker-的用户名字空間功能" tabindex="-1">使用 Docker 的用户名字空間功能 <a class="header-anchor" href="#使用-docker-的用户名字空間功能" aria-label="Permalink to “使用 Docker 的用户名字空間功能”">​</a></h1><p><ruby>用户名字空間<rt>User Namespaces</rt></ruby> 於 Docker 1.10 版本正式納入其中，該功能允許主機系統將自身的 <code>uid</code> 和 <code>gid</code> 映射為容器進程中的另一個 <code>uid</code> 和 <code>gid</code>。這對 Docker 的安全性來説是一項巨大的改進。下面我會通過一個案例來展示一下用户名字空間能夠解決的問題，以及如何啓用該功能。</p><h3 id="創建一個-docker-machine" tabindex="-1">創建一個 Docker Machine <a class="header-anchor" href="#創建一個-docker-machine" aria-label="Permalink to “創建一個 Docker Machine”">​</a></h3><p>如果你已經創建好了一台用來試驗用户名字空間的 docker <ruby>機器<rt>Machine</rt></ruby>，那麼可以跳過這一步。我在自己的 Macbook 上安裝了 Docker Toolbox，因此我只需用 <code>docker-machine</code> 命令就很簡單地創建一個基於 VirtualBox 的 Docker 機器（這裏假設主機名為 <code>host1</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Create host1</span></span>
<span class="line"><span>$ docker-machine create --driver virtualbox host1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Login to host1</span></span>
<span class="line"><span>$ docker-machine ssh host1</span></span></code></pre></div><h3 id="理解在用户名字空間未啓用的情況下-非-root-用户能做什麼" tabindex="-1">理解在用户名字空間未啓用的情況下，非 root 用户能做什麼 <a class="header-anchor" href="#理解在用户名字空間未啓用的情況下-非-root-用户能做什麼" aria-label="Permalink to “理解在用户名字空間未啓用的情況下，非 root 用户能做什麼”">​</a></h3><p>在啓用用户名字空間前，我們先來看一下會有什麼問題。Docker 到底哪個地方做錯了？首先，使用 Docker 的一大優勢在於用户在容器中可以擁有 root 權限，因此用户可以很方便地安裝軟件包。但是在 Linux 容器技術中這也是一把雙刃劍。只要經過少許操作，非 root 用户就能以 root 的權限訪問主機系統中的內容，比如 <code>/etc</code>。下面是操作步驟。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Run a container and mount host1&#39;s /etc onto /root/etc</span></span>
<span class="line"><span>$ docker run --rm -v /etc:/root/etc -it ubuntu</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Make some change on /root/etc/hosts</span></span>
<span class="line"><span>root@34ef23438542:/# vi /root/etc/hosts</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Exit from the container</span></span>
<span class="line"><span>root@34ef23438542:/# exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Check /etc/hosts</span></span>
<span class="line"><span>$ cat /etc/hosts</span></span></code></pre></div><p>你可以看到，步驟簡單到難以置信，很明顯 Docker 並不適用於運行在多人共享的電腦上。但是現在，通過用户名字空間，Docker 可以避免這個問題。</p><h3 id="啓用用户名字空間" tabindex="-1">啓用用户名字空間 <a class="header-anchor" href="#啓用用户名字空間" aria-label="Permalink to “啓用用户名字空間”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Create a user called &quot;dockremap&quot;</span></span>
<span class="line"><span>$ sudo adduser dockremap</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Setup subuid and subgid</span></span>
<span class="line"><span>$ sudo sh -c &#39;echo dockremap:500000:65536 &gt; /etc/subuid&#39;</span></span>
<span class="line"><span>$ sudo sh -c &#39;echo dockremap:500000:65536 &gt; /etc/subgid&#39;</span></span></code></pre></div><p>然後，打開 <code>/etc/init.d/docker</code>，並在 <code>/usr/local/bin/docker daemon</code> 後面加上 <code>--userns-remap=default</code>，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/init.d/docker</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/local/bin/docker daemon --userns-remap=default -D -g &quot;$DOCKER_DIR&quot; -H unix:// $DOCKER_HOST $EXTRA_ARGS &gt;&gt; &quot;$DOCKER_LOGFILE&quot; 2&gt;&amp;1 &amp;</span></span></code></pre></div><p>然後重啓 Docker：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /etc/init.d/docker restart</span></span></code></pre></div><p>這就完成了！</p><p><strong>注意</strong>：若你使用的是 CentOS 7，則你需要了解兩件事。</p><ol><li><p>內核默認並沒有啓用用户名字空間。運行下面命令並重啓系統，可以啓用該功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo grubby --args=&quot;user_namespace.enable=1&quot; \\</span></span>
<span class="line"><span>    --update-kernel=/boot/vmlinuz-3.10.0-XXX.XX.X.el7.x86_64</span></span></code></pre></div></li><li><p>CentOS 7 使用 <code>systemctl</code> 來管理服務，因此你需要編輯的文件是 <code>/usr/lib/systemd/system/docker.service</code>。</p></li></ol><h3 id="確認用户名字空間是否正常工作" tabindex="-1">確認用户名字空間是否正常工作 <a class="header-anchor" href="#確認用户名字空間是否正常工作" aria-label="Permalink to “確認用户名字空間是否正常工作”">​</a></h3><p>若一切都配置妥當，則你應該無法再在容器中編輯 host1 上的 <code>/etc</code> 了。讓我們來試一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Create a container and mount host1&#39;s /etc to container&#39;s /root/etc</span></span>
<span class="line"><span>$ docker run --rm -v /etc:/root/etc -it ubuntu</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Check the owner of files in /root/etc, which should be &quot;nobody nogroup&quot;.</span></span>
<span class="line"><span>root@d5802c5e670a:/# ls -la /root/etc</span></span>
<span class="line"><span>total 180</span></span>
<span class="line"><span>drwxr-xr-x 11 nobody nogroup 1100 Mar 21 23:31 .</span></span>
<span class="line"><span>drwx------ 3 root root 4096 Mar 21 23:50 ..</span></span>
<span class="line"><span>lrwxrwxrwx 1 nobody nogroup 19 Mar 21 23:07 acpi -&gt; /usr/local/etc/acpi</span></span>
<span class="line"><span>-rw-r--r-- 1 nobody nogroup 48 Mar 10 22:09 boot2docker</span></span>
<span class="line"><span>drwxr-xr-x 2 nobody nogroup 60 Mar 21 23:07 default</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Try creating a file in /root/etc</span></span>
<span class="line"><span>root@d5802c5e670a:/# touch /root/etc/test</span></span>
<span class="line"><span>touch: cannot touch &#39;/root/etc/test&#39;: Permission denied</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Try deleting a file</span></span>
<span class="line"><span>root@d5802c5e670a:/# rm /root/etc/hostname</span></span>
<span class="line"><span>rm: cannot remove &#39;/root/etc/hostname&#39;: Permission denied</span></span></code></pre></div><p>好了，太棒了。這就是用户名字空間的工作方式。</p><hr>`,23)),o("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://coderwall.com/p/s_ydlq/using-user-namespaces-on-docker"},{default:t(()=>[...s[0]||(s[0]=[a("https://coderwall.com/p/s_ydlq/using-user-namespaces-on-docker",-1)])]),_:1})]),o("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://coderwall.com/kjtanaka"},{default:t(()=>[...s[2]||(s[2]=[a("Koji Tanaka",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/pityonline"},{default:t(()=>[...s[5]||(s[5]=[a("pityonline",-1)])]),_:1})]),o("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=i(d,[["render",h]]);export{y as __pageData,C as default};
